using ShiftTrack.Domain.Common.Abstractions;
using ShiftTrack.Domain.Modules.Communication.Messenger.Enums;

namespace ShiftTrack.Domain.Modules.Communication.Messenger.Entities;

/// <summary>A message in a conversation. The sender is <see cref="AuditableEntity.AuthorId"/>.</summary>
public class Message : AuditableEntity
{
    public long Id { get; set; }

    public long ConversationId { get; set; }
    public Conversation Conversation { get; set; }

    public MessageType Type { get; set; }

    public string Text { get; set; }

    /// <summary>Id generated by the client, so a request sent twice creates one message.</summary>
    public Guid? ClientMessageId { get; set; }

    public long? ReplyToMessageId { get; set; }
    public Message ReplyToMessage { get; set; }

    public DateTime? EditedAt { get; set; }

    /// <summary>A deleted message stays in the history as "deleted", without its text.</summary>
    public DateTime? DeletedAt { get; set; }

    public bool IsDeleted => DeletedAt is not null;

    public List<MessageAttachment> Attachments { get; set; } = [];

    public List<MessageMention> Mentions { get; set; } = [];
}
